import React from 'react';
import './Hero.css';

const Hero = () => {
  return (
    <section className="hero" id="home">
      <div className="hero-bg">
        <div className="paint-drops">
          {[...Array(6)].map((_, i) => (
            <div
              key={i}
              className={`paint-drop drop-${i + 1}`}
            />
          ))}
        </div>
      </div>

      <div className="container">
        <div className="hero-content">
          <h1 className="hero-title">
            Premium <span className="highlight">Water-Based</span> Paints
          </h1>

          <p className="hero-subtitle">
            Eco-friendly, vibrant colors that bring your walls to life with zero harmful chemicals
          </p>

          <div className="hero-buttons">
            <button className="btn btn-primary">Explore Products</button>
            <button className="btn btn-secondary">Get Quote</button>
          </div>
        </div>

        <div className="hero-image">
          <div className="paint-bucket">
            <div className="bucket-body"></div>
            <div className="paint-splash"></div>
            <div className="brush"></div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Hero;
